const input = $json.body ?? $json;
const hasContact = Boolean(input.leadData?.email || input.leadData?.phone);
if (input.workflowKey !== 'lead.capture' || !input.actionId || !input.tenantId || !input.sessionId || input.validationPass !== true || input.score < 70 || !input.leadData?.name || !hasContact || !Array.isArray(input.conversation)) throw new Error('Lead validation failed');
return [{ json: input }];
